/// Raven `Droid_Run`.
///
/// Source: `oracle/oracle/codemp/game/NPC_AI_Droid.c:175-200`
pub fn Droid_Run() {
    unsafe {
        // SAFETY: NPC, NPCInfo, level, ucmd accessed through game context.
        R2D2_PartsMove();

        if (*NPCInfo).localState == LSTATE_BACKINGUP {
            ucmd.forwardmove = -127;
            (*NPCInfo).desiredYaw += 5.0;

            (*NPCInfo).localState = LSTATE_NONE;  // So he doesn't constantly backup.
        } else {
            ucmd.forwardmove = 64;
            // If we have somewhere to go, then do that
            if !UpdateGoal().is_null() {
                if NPC_MoveToGoal(qfalse) != 0 {
                    (*NPCInfo).desiredYaw += ((*level).time * 0.5).sin() * 5.0;  // Weaves side to side
                }
            }
        }

        NPC_UpdateAngles(qtrue, qtrue);
    }
}

/// Raven `Droid_Spin`.
///
/// Source: `oracle/oracle/codemp/game/NPC_AI_Droid.c:207-266`
pub fn Droid_Spin() {
    unsafe {
        // SAFETY: NPC, NPCInfo accessed through game context; trap called through seam.
        let mut dir: vec3_t = [0.0, 0.0, 1.0];

        R2D2_TurnAnims();

        // Head is gone, spin and spark
        if (*(*NPC).client).NPC_class == crate::prelude::CLASS_R5D2
            || (*(*NPC).client).NPC_class == crate::prelude::CLASS_R2D2
        {
            // No head?
            if trap::G2API_GetSurfaceRenderStatus(&mut (*NPC).ghoul2, 0, b"head\0".as_ptr() as *const c_char) > 0 {
                if TIMER_Done(NPC, b"smoke\0".as_ptr() as *const c_char) != 0
                    && TIMER_Done(NPC, b"droidsmoketotal\0".as_ptr() as *const c_char) == 0
                {
                    TIMER_Set(NPC, b"smoke\0".as_ptr() as *const c_char, 100);
                    G_PlayEffectID(
                        G_EffectIndex(b"volumetric/droid_smoke\0".as_ptr() as *const c_char),
                        (*NPC).r.currentOrigin,
                        dir,
                    );
                }

                if TIMER_Done(NPC, b"droidspark\0".as_ptr() as *const c_char) != 0 {
                    TIMER_Set(NPC, b"droidspark\0".as_ptr() as *const c_char, Q_irand(100, 500));
                    G_PlayEffectID(
                        G_EffectIndex(b"sparks/spark\0".as_ptr() as *const c_char),
                        (*NPC).r.currentOrigin,
                        dir,
                    );
                }

                ucmd.forwardmove = Q_irand(-64, 64);

                if TIMER_Done(NPC, b"roam\0".as_ptr() as *const c_char) != 0 {
                    TIMER_Set(NPC, b"roam\0".as_ptr() as *const c_char, Q_irand(250, 1000));
                    (*NPCInfo).desiredYaw = Q_irand(0, 360) as f32;  // Go in random directions
                }
            } else {
                if TIMER_Done(NPC, b"roam\0".as_ptr() as *const c_char) != 0 {
                    (*NPCInfo).localState = LSTATE_NONE;
                } else {
                    (*NPCInfo).desiredYaw = AngleNormalize360((*NPCInfo).desiredYaw + 40.0);  // Spin around
                }
            }
        } else {
            if TIMER_Done(NPC, b"roam\0".as_ptr() as *const c_char) != 0 {
                (*NPCInfo).localState = LSTATE_NONE;
            } else {
                (*NPCInfo).desiredYaw = AngleNormalize360((*NPCInfo).desiredYaw + 40.0);  // Spin around
            }
        }

        NPC_UpdateAngles(qtrue, qtrue);
    }
}

/// Raven `NPC_Droid_Pain`.
