        let mod_ = gPainMOD;
        let pain_chance: f32;

        // Copy last path angles to entity angles
        let npc_info = (*self_).NPC;
        let src_angles = (*npc_info).lastPathAngles;
        (*self_).s.angles[0] = src_angles[0];
        (*self_).s.angles[1] = src_angles[1];
        (*self_).s.angles[2] = src_angles[2];

        if (*(*self_).client).NPC_class == crate::prelude::CLASS_R5D2 {
            pain_chance = NPC_GetPainChance(self_, damage);

            // Put it in pain
            if mod_ == crate::prelude::MOD_DEMP2
                || mod_ == crate::prelude::MOD_DEMP2_ALT
                || (rand() as f32 / 2147483647.0) < pain_chance
            {
                // Health is between 0-30 or was hit by a DEMP2 so pop his head
                if (*self_).s.m_iVehicleNum == 0
                    && ((*self_).health < 30
                        || mod_ == crate::prelude::MOD_DEMP2
                        || mod_ == crate::prelude::MOD_DEMP2_ALT)
                {
                    if ((*self_).spawnflags & 2) == 0 {
                        // Doesn't have to ALWAYSDIE
                        if (*npc_info).localState != LSTATE_SPINNING
                            && trap::G2API_GetSurfaceRenderStatus(
                                &mut (*self_).ghoul2,
                                0,
                                b"head\0".as_ptr() as *const c_char,
                            ) <= 0
                        {
                            NPC_SetSurfaceOnOff(self_, b"head\0".as_ptr() as *const c_char, TURN_OFF);

                            if (*(*self_).client).ps.m_iVehicleNum != 0 {
                                let mut up: vec3_t = [0.0; 3];
                                AngleVectors((*self_).r.currentAngles, [0.0; 3], [0.0; 3], up);
                                G_PlayEffectID(
                                    G_EffectIndex(
                                        b"chunks/r5d2head_veh\0".as_ptr() as *const c_char,
                                    ),
                                    (*self_).r.currentOrigin,
                                    up,
                                );
                            } else {
                                G_PlayEffectID(
                                    G_EffectIndex(b"small_chunks\0".as_ptr() as *const c_char),
                                    (*self_).r.currentOrigin,
                                    vec3_origin,
                                );
                                G_PlayEffectID(
                                    G_EffectIndex(b"chunks/r5d2head\0".as_ptr() as *const c_char),
                                    (*self_).r.currentOrigin,
                                    vec3_origin,
                                );
                            }

                            (*(*self_).client).ps.electrifyTime = (*level).time + 3000;

                            TIMER_Set(self_, b"droidsmoketotal\0".as_ptr() as *const c_char, 5000);
                            TIMER_Set(self_, b"droidspark\0".as_ptr() as *const c_char, 100);
                            (*npc_info).localState = LSTATE_SPINNING;
                        }
                    }
                } else {
                    // Just give him normal pain for a little while
                    let legsAnim = (*(*self_).client).ps.legsAnim;

                    if legsAnim == crate::prelude::BOTH_STAND2 {
                        // On two legs?
                        anim = crate::prelude::BOTH_PAIN1;
                    } else {
                        // On three legs
                        anim = crate::prelude::BOTH_PAIN2;
                    }

                    NPC_SetAnim(
                        self_,
                        crate::prelude::SETANIM_BOTH,
                        anim,
                        crate::prelude::SETANIM_FLAG_OVERRIDE | crate::prelude::SETANIM_FLAG_HOLD,
                    );

                    // Spin around in pain
                    (*npc_info).localState = LSTATE_SPINNING;
                    TIMER_Set(self_, b"roam\0".as_ptr() as *const c_char, Q_irand(1000, 2000));
                }
            }
        } else if (*(*self_).client).NPC_class == crate::prelude::CLASS_MOUSE {
            if mod_ == crate::prelude::MOD_DEMP2 || mod_ == crate::prelude::MOD_DEMP2_ALT {
                (*npc_info).localState = LSTATE_SPINNING;
                (*(*self_).client).ps.electrifyTime = (*level).time + 3000;
            } else {
                (*npc_info).localState = LSTATE_BACKINGUP;
            }

            (*npc_info).scriptFlags &= !crate::prelude::SCF_LOOK_FOR_ENEMIES;
        } else if (*(*self_).client).NPC_class == crate::prelude::CLASS_R2D2 {
            pain_chance = NPC_GetPainChance(self_, damage);

            if mod_ == crate::prelude::MOD_DEMP2
                || mod_ == crate::prelude::MOD_DEMP2_ALT
                || (rand() as f32 / 2147483647.0) < pain_chance
            {
                // Health is between 0-30 or was hit by a DEMP2 so pop his head
                if (*self_).s.m_iVehicleNum == 0
                    && ((*self_).health < 30
                        || mod_ == crate::prelude::MOD_DEMP2
                        || mod_ == crate::prelude::MOD_DEMP2_ALT)
                {
                    if ((*self_).spawnflags & 2) == 0 {
                        // Doesn't have to ALWAYSDIE
                        if (*npc_info).localState != LSTATE_SPINNING
                            && trap::G2API_GetSurfaceRenderStatus(
                                &mut (*self_).ghoul2,
                                0,
                                b"head\0".as_ptr() as *const c_char,
                            ) <= 0
                        {
                            NPC_SetSurfaceOnOff(self_, b"head\0".as_ptr() as *const c_char, TURN_OFF);

                            if (*(*self_).client).ps.m_iVehicleNum != 0 {
                                let mut up: vec3_t = [0.0; 3];
                                AngleVectors((*self_).r.currentAngles, [0.0; 3], [0.0; 3], up);
                                G_PlayEffectID(
                                    G_EffectIndex(
                                        b"chunks/r2d2head_veh\0".as_ptr() as *const c_char,
                                    ),
                                    (*self_).r.currentOrigin,
                                    up,
                                );
                            } else {
                                G_PlayEffectID(
                                    G_EffectIndex(b"small_chunks\0".as_ptr() as *const c_char),
                                    (*self_).r.currentOrigin,
                                    vec3_origin,
                                );
                                G_PlayEffectID(
                                    G_EffectIndex(b"chunks/r2d2head\0".as_ptr() as *const c_char),
                                    (*self_).r.currentOrigin,
                                    vec3_origin,
                                );
                            }

                            (*(*self_).client).ps.electrifyTime = (*level).time + 3000;

                            TIMER_Set(self_, b"droidsmoketotal\0".as_ptr() as *const c_char, 5000);
                            TIMER_Set(self_, b"droidspark\0".as_ptr() as *const c_char, 100);
                            (*npc_info).localState = LSTATE_SPINNING;
                        }
                    }
                } else {
                    // Just give him normal pain for a little while
                    let legsAnim = (*(*self_).client).ps.legsAnim;

                    if legsAnim == crate::prelude::BOTH_STAND2 {
                        // On two legs?
                        anim = crate::prelude::BOTH_PAIN1;
                    } else {
                        // On three legs
                        anim = crate::prelude::BOTH_PAIN2;
                    }

                    NPC_SetAnim(
                        self_,
                        crate::prelude::SETANIM_BOTH,
                        anim,
                        crate::prelude::SETANIM_FLAG_OVERRIDE | crate::prelude::SETANIM_FLAG_HOLD,
                    );

                    // Spin around in pain
                    (*npc_info).localState = LSTATE_SPINNING;
                    TIMER_Set(self_, b"roam\0".as_ptr() as *const c_char, Q_irand(1000, 2000));
                }
            }
        } else if (*(*self_).client).NPC_class == crate::prelude::CLASS_INTERROGATOR
            && (mod_ == crate::prelude::MOD_DEMP2 || mod_ == crate::prelude::MOD_DEMP2_ALT)
            && !other.is_null()
        {
            let mut dir: vec3_t = [0.0; 3];

            dir[0] = (*self_).r.currentOrigin[0] - (*other).r.currentOrigin[0];
            dir[1] = (*self_).r.currentOrigin[1] - (*other).r.currentOrigin[1];
            dir[2] = (*self_).r.currentOrigin[2] - (*other).r.currentOrigin[2];
            VectorNormalize(dir);

            (*(*self_).client).ps.velocity[0] += 550.0 * dir[0];
            (*(*self_).client).ps.velocity[1] += 550.0 * dir[1];
            (*(*self_).client).ps.velocity[2] += 550.0 * dir[2];
            (*(*self_).client).ps.velocity[2] -= 127.0;
        }

        NPC_Pain(self_, attacker, damage);
